const { z } = require("zod");
function symptom(msg) { console.error("FAIL: " + msg); process.exit(1); }
function broken(msg) { console.error("ERROR: " + msg); process.exit(2); }
const schema = z.number().multipleOf(1e-7);
for (const v of [0, 1e-7, 2e-7, 3e-7]) if (!schema.safeParse(v).success) broken("multipleOf(1e-7) rejected the true multiple " + v);
if (schema.safeParse(2.5e-7).success) symptom("z.number().multipleOf(1e-7) accepts 2.5e-7");
console.log("OK: z.number().multipleOf(1e-7) rejects 2.5e-7");

